 assert i not in path
 s={i}
 for j in g[i]['requires']: s.update(reach(j,(*path,i)))
 return s
sets=[reach(x) for x in d['candidate']['requires']]
print([len(s) for s in sets],len(set.union(*sets)),len(g))
for i in [202,209,213,216,217,1031,1032,1033,1034,1093,1094,1095,1096,1097]:
 print(i,Path('canonical-input.json').read_text().splitlines()[i-1][:108])
